//! Generates the plugin's permissions (`permissions/autogenerated/`, committed) from its command list. The host app
//! grants them in one capability for its main window only (ADR 0015 § 4). For phones it also builds the animal set
//! into the plugin (`../avatars/animals`), since an Android app's resources are no files the core can read.

use std::path::{Path, PathBuf};

const COMMANDS: &[&str] = &[
    "join",
    "status",
    "send",
    "set_enabled",
    "image",
    "animal",
    "animals",
    "classify",
    "stage",
    "token",
    "open_file",
    "show_file",
    "open_settings",
    "open_url",
    "shareable",
    "drop_paths",
    "drag_over",
];

/// `OUT_DIR/animals.rs`: the manifest and every SVG, by their paths in the set; empty off phones.
fn animal_set() {
    let out = PathBuf::from(std::env::var_os("OUT_DIR").expect("OUT_DIR"));
    let target = std::env::var("CARGO_CFG_TARGET_OS").unwrap_or_default();
    let set = Path::new(env!("CARGO_MANIFEST_DIR")).join("../avatars/animals");
    let mut files = vec!["manifest.json".to_owned()];
    if target == "android" || target == "ios" {
        println!("cargo:rerun-if-changed={}", set.display());
        let mut svgs: Vec<String> = std::fs::read_dir(set.join("svg"))
            .expect("the animal set")
            .filter_map(|e| e.ok()?.file_name().into_string().ok())
            .filter(|name| name.ends_with(".svg"))
            .map(|name| format!("svg/{name}"))
            .collect();
        svgs.sort();
        files.extend(svgs);
    } else {
        files.clear();
    }
    let entries: String = files
        .iter()
        .map(|name| format!("    ({name:?}, include_bytes!({:?})),\n", set.join(name).display().to_string()))
        .collect();
    let source = format!("pub static FILES: &[(&str, &[u8])] = &[\n{entries}];\n");
    std::fs::write(out.join("animals.rs"), source).expect("animals.rs");
}

fn main() {
    animal_set();
    // Phones: the Kotlin (android/) and Swift (ios/) halves, the platform's part of nearby discovery and Bluetooth
    // (src/nearby.rs) and of the key store, backups and sharing (src/phone/native.rs). They answer Rust only: none
    // of their commands is in COMMANDS, so no permission grants them to a page.
    tauri_plugin::Builder::new(COMMANDS).android_path("android").ios_path("ios").build();
}
